import {authOptions} from '@/lib/auth';
import {stripe} from '@/lib/stripe';
import {getServerSession} from 'next-auth';
import {NextRequest} from 'next/server';

export async function POST(req: NextRequest) {
  const json = await req.json();
  const {financialAccount} = json;
  try {
    const session = await getServerSession(authOptions);
    const accountId = session?.user.stripeAccount.id;

    await stripe.testHelpers.treasury.receivedCredits.create(
      {
        amount: 1000,
        currency: 'usd',
        financial_account: financialAccount,
        network: 'ach',
      },
      {
        stripeAccount: accountId,
      }
    );

    return new Response('Success', {
      status: 200,
      headers: {'Content-Type': 'application/json'},
    });
  } catch (error: any) {
    console.error(
      'An error occurred when calling the Stripe API to create payouts',
      error
    );
    return new Response(error.message, {status: 500});
  }
}

import {getServerSession} from 'next-auth/next';
import {authOptions} from '@/lib/auth';
import {stripe} from '@/lib/stripe';

export async function POST() {
  try {
    const session = await getServerSession(authOptions);

    const connected_account = session!.user.stripeAccount.id;
    const offer = (
      await stripe.capital.financingOffers.list({connected_account, limit: 1})
    ).data
      .filter((o) => o.status === 'delivered')
      .at(0);

    if (offer === undefined) {
      throw Error(
        'Unable to find offer with status `delivered` for connected account: ' +
          connected_account
      );
    }

    await stripe.rawRequest(
      'POST',
      `/v1/capital/financing_offers/${offer!.id}/expire`,
      {}
    );

    return new Response(
      JSON.stringify({
        offer,
      }),
      {status: 200, headers: {'Content-Type': 'application/json'}}
    );
  } catch (error: any) {
    console.error(
      'An error occurred when calling the Stripe API to expire test financing offer',
      error
    );
    return new Response(error.message, {status: 500});
  }
}

