        doStream: jest.fn(),
      } as any;

      expect(() => {
        meteredModel(mockModel, TEST_API_KEY, 'cus_test123');
      }).toThrow('Only LanguageModelV2 and LanguageModelV3 models are supported');
    });

    it('should throw error for model with unknown specification version', () => {
      const mockModel = {
        modelId: 'mock-model-v99',
        provider: 'future-provider',
        specificationVersion: 'v99',
        doGenerate: jest.fn(),
        doStream: jest.fn(),
      } as any;

      expect(() => {
        meteredModel(mockModel, TEST_API_KEY, 'cus_test123');
      }).toThrow('Only LanguageModelV2 and LanguageModelV3 models are supported');
    });

    it('should provide clear error message', () => {
      const mockModel = {specificationVersion: 'v1'} as any;

      expect(() => {
        meteredModel(mockModel, TEST_API_KEY, 'cus_test123');
      }).toThrow(/Only LanguageModelV2 and LanguageModelV3 models are supported/);
      expect(() => {
        meteredModel(mockModel, TEST_API_KEY, 'cus_test123');
      }).toThrow(/Please use a supported provider/);
    });
  });

  describe('Provider Support', () => {
    it('should support any v2 provider name', async () => {
      const customProviderModel = {
        modelId: 'custom-model-123',
        provider: 'my-custom-provider',
        specificationVersion: 'v2',
        doGenerate: jest.fn().mockResolvedValue({
          text: 'Custom response',
          usage: {
            inputTokens: 10,
            outputTokens: 5,
          },
          finishReason: 'stop',
          rawResponse: {},
          warnings: [],
        }),
        doStream: jest.fn(),
      } as any;

      const wrapped = meteredModel(
        customProviderModel,
        TEST_API_KEY,
        'cus_test123'
      );

      await wrapped.doGenerate({
        inputFormat: 'prompt',
        mode: {type: 'regular'},
        prompt: [],
      } as any);

      // Wait for fire-and-forget logging to complete
      await new Promise(resolve => setImmediate(resolve));

      expect(wrapped).toBeDefined();
      expect(wrapped.provider).toBe('my-custom-provider');
      expect(mockMeterEventsCreate).toHaveBeenCalledWith(
        expect.objectContaining({
          payload: expect.objectContaining({
            model: 'my-custom-provider/custom-model-123',
          }),
        })
      );
    });

    it('should provide helpful error message for unsupported models', () => {
      const unsupportedModel = {
        modelId: 'test',
        provider: 'test-provider',
        specificationVersion: 'v1',
      } as any;

      try {
        meteredModel(unsupportedModel, TEST_API_KEY, 'cus_test123');
        fail('Should have thrown an error');
      } catch (error: any) {
        expect(error.message).toContain('Only LanguageModelV2 and LanguageModelV3 models are supported');
        expect(error.message).toContain('specificationVersion "v1"');
        expect(error.message).toContain('OpenAI, Anthropic, Google');
      }
    });
  });

  describe('Edge Cases', () => {
    it('should handle model with missing usage data', async () => {
      const model = {
        modelId: 'test-model',
        provider: 'test-provider',
        specificationVersion: 'v2',
        doGenerate: jest.fn().mockResolvedValue({
          text: 'Response',
          usage: undefined,
          finishReason: 'stop',
          rawResponse: {},
          warnings: [],
        }),
        doStream: jest.fn(),
      } as any;

      const wrapped = meteredModel(model, TEST_API_KEY, 'cus_test123');

      await wrapped.doGenerate({
        inputFormat: 'prompt',
        mode: {type: 'regular'},
        prompt: [],
      } as any);

      // Wait for fire-and-forget logging to complete
      await new Promise(resolve => setImmediate(resolve));

      // Should not create meter events with 0 tokens (code only sends when > 0)
      expect(mockMeterEventsCreate).toHaveBeenCalledTimes(0);
    });

    it('should handle model with partial usage data', async () => {
      const model = {
        modelId: 'test-model',
        provider: 'test-provider',
        specificationVersion: 'v2',
        doGenerate: jest.fn().mockResolvedValue({
          text: 'Response',
          usage: {
            inputTokens: 10,
            outputTokens: undefined,
          },
          finishReason: 'stop',
          rawResponse: {},
          warnings: [],
        }),
        doStream: jest.fn(),
      } as any;

      const wrapped = meteredModel(model, TEST_API_KEY, 'cus_test123');

      await wrapped.doGenerate({
        inputFormat: 'prompt',
        mode: {type: 'regular'},
        prompt: [],
      } as any);

      // Wait for fire-and-forget logging to complete
      await new Promise(resolve => setImmediate(resolve));

      // Should handle partial data gracefully - only sends event for input tokens
      // Output tokens with value 0 are not sent (code only sends when > 0)
      expect(mockMeterEventsCreate).toHaveBeenCalledTimes(1);
      expect(mockMeterEventsCreate).toHaveBeenCalledWith(
        expect.objectContaining({
          payload: expect.objectContaining({
            value: '10',
            token_type: 'input',
          }),
        })
      );
    });
  });
});

/**
 * Tests for AI SDK billing wrapper V3 with OpenAI models
 * Uses mock V3 models to verify meter events are sent correctly
 */

import Stripe from 'stripe';
import {meteredModel} from '../index';

jest.mock('stripe');

function createMockV3Model(
  modelId: string,
  provider: string = 'openai.chat'
) {
  return {
    modelId,
    provider,
    specificationVersion: 'v3' as const,
    supportedUrls: {},
    doGenerate: jest.fn(),
    doStream: jest.fn(),
  };
}

describe('AI SDK Billing Wrapper V3 - OpenAI', () => {
  let mockMeterEventsCreate: jest.Mock;
  const TEST_API_KEY = 'sk_test_mock_key';

  beforeEach(() => {
    mockMeterEventsCreate = jest.fn().mockResolvedValue({});

    (Stripe as unknown as jest.Mock).mockImplementation(() => ({
      v2: {
        billing: {
          meterEvents: {
            create: mockMeterEventsCreate,
          },
        },
      },
    }));
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  it('should create wrapper that preserves model properties', () => {
    const originalModel = createMockV3Model('gpt-4o-mini');
    const wrappedModel = meteredModel(
      originalModel as any,
      TEST_API_KEY,
      'cus_test123'
    );

    expect(wrappedModel.modelId).toBe('gpt-4o-mini');
    expect(wrappedModel.provider).toBe('openai.chat');
    expect(wrappedModel.specificationVersion).toBe('v3');
  });

  it('should wrap doGenerate and send meter events with V3 usage format', async () => {
    const originalModel = createMockV3Model('gpt-4o-mini');
    originalModel.doGenerate.mockResolvedValue({
      content: [{type: 'text', text: 'Test response'}],
      finishReason: {unified: 'stop', raw: 'stop'},
      usage: {
        inputTokens: {
          total: 10,
          noCache: undefined,
          cacheRead: undefined,
          cacheWrite: undefined,
        },
        outputTokens: {
          total: 5,
          text: undefined,
          reasoning: undefined,
        },
      },
      warnings: [],
    });

    const wrappedModel = meteredModel(
      originalModel as any,
      TEST_API_KEY,
      'cus_test123'
    );

    const result = await wrappedModel.doGenerate({
      prompt: [{role: 'user', content: [{type: 'text', text: 'Test'}]}],
    } as any);

    expect((result as any).content[0].text).toBe('Test response');

    await new Promise((resolve) => setImmediate(resolve));

    expect(mockMeterEventsCreate).toHaveBeenCalledTimes(2);
    expect(mockMeterEventsCreate).toHaveBeenCalledWith(
      expect.objectContaining({
        event_name: 'token-billing-tokens',
        payload: expect.objectContaining({
          stripe_customer_id: 'cus_test123',
          value: '10',
          model: 'openai/gpt-4o-mini',
          token_type: 'input',
        }),
      })
    );
    expect(mockMeterEventsCreate).toHaveBeenCalledWith(
      expect.objectContaining({
        event_name: 'token-billing-tokens',
        payload: expect.objectContaining({
          value: '5',
          token_type: 'output',
        }),
      })
    );
  });

  it('should normalize OpenAI model names', async () => {
    const originalModel = createMockV3Model('gpt-4-turbo-2024-04-09');
    originalModel.doGenerate.mockResolvedValue({
      content: [{type: 'text', text: 'Test'}],
      finishReason: {unified: 'stop', raw: 'stop'},
      usage: {
        inputTokens: {total: 5, noCache: undefined, cacheRead: undefined, cacheWrite: undefined},
        outputTokens: {total: 2, text: undefined, reasoning: undefined},
      },
      warnings: [],
    });

    const wrappedModel = meteredModel(
      originalModel as any,
      TEST_API_KEY,
      'cus_test123'
    );

    await wrappedModel.doGenerate({
      prompt: [{role: 'user', content: [{type: 'text', text: 'Test'}]}],
    } as any);

    await new Promise((resolve) => setImmediate(resolve));

    // The meter-event-logging normalizes the model name (date suffix removed)
    expect(mockMeterEventsCreate).toHaveBeenCalledWith(
      expect.objectContaining({
        payload: expect.objectContaining({
          model: 'openai/gpt-4-turbo',
        }),
      })
    );
  });

  it('should handle missing usage gracefully', async () => {
    const originalModel = createMockV3Model('gpt-4o-mini');
    originalModel.doGenerate.mockResolvedValue({
      content: [{type: 'text', text: 'Test'}],
      finishReason: {unified: 'stop', raw: 'stop'},
      usage: undefined,
      warnings: [],
    });

    const wrappedModel = meteredModel(
      originalModel as any,
      TEST_API_KEY,
      'cus_test123'
    );

    await wrappedModel.doGenerate({
      prompt: [{role: 'user', content: [{type: 'text', text: 'Test'}]}],
    } as any);

    await new Promise((resolve) => setImmediate(resolve));

    expect(mockMeterEventsCreate).toHaveBeenCalledTimes(0);
  });

  it('should handle V3 usage with cache info', async () => {
    const originalModel = createMockV3Model('gpt-4o-mini');
    originalModel.doGenerate.mockResolvedValue({
      content: [{type: 'text', text: 'Test'}],
      finishReason: {unified: 'stop', raw: 'stop'},
      usage: {
        inputTokens: {
          total: 100,
          noCache: 80,
          cacheRead: 20,
          cacheWrite: 0,
        },
        outputTokens: {
          total: 50,
          text: 40,
          reasoning: 10,
        },
      },
      warnings: [],
    });

    const wrappedModel = meteredModel(
      originalModel as any,
      TEST_API_KEY,
      'cus_test123'
    );

    await wrappedModel.doGenerate({
      prompt: [{role: 'user', content: [{type: 'text', text: 'Test'}]}],
    } as any);

    await new Promise((resolve) => setImmediate(resolve));

    expect(mockMeterEventsCreate).toHaveBeenCalledTimes(2);
    expect(mockMeterEventsCreate).toHaveBeenCalledWith(
      expect.objectContaining({
        payload: expect.objectContaining({
          value: '100',
          token_type: 'input',
        }),
      })
    );
    expect(mockMeterEventsCreate).toHaveBeenCalledWith(
      expect.objectContaining({
        payload: expect.objectContaining({
          value: '50',
          token_type: 'output',
        }),
      })
    );
  });
});

